"""Generate Terraform modules from the committed provider schema dumps.

Authoring-side tool: runs here via `make generate`, output is committed.
Consuming environments never run it. Stdlib-only, Python 3.6-floor syntax
— see AGENTS.md rules 5-7.
"""
from tools.tfschema import classify_attributes, hcl_type, load_resource


def _header(resource_type, provider):
    return (
        "# GENERATED by tools/gen_module.py from schemas/provider/%s.json"
        " — do not edit.\n# Regenerate: make generate\n\n" % provider
    )


def _provider_of(resource_type):
    return resource_type.split("_", 1)[0]


def _block_object_type(block, indent):
    """HCL object({...}) type for a nested block's input shape."""
    cls = classify_attributes(block)
    pad = " " * (indent + 2)
    lines = []
    for name in cls["required"] + cls["optional"]:
        attr_t = hcl_type(block["attributes"][name]["type"], indent + 2)
        lines.append("%s%s = optional(%s)" % (pad, name, attr_t))
    for name, bt in sorted((block.get("block_types") or {}).items()):
        lines.append(
            "%s%s = optional(%s)" % (pad, name, _block_input_type(bt, indent + 2))
        )
    return "object({\n%s\n%s})" % ("\n".join(lines), " " * indent)


def _block_input_type(block_type, indent):
    inner = _block_object_type(block_type["block"], indent)
    mode = block_type["nesting_mode"]
    if mode == "single":
        return inner
    if mode in ("list", "set"):
        return "%s(%s)" % (mode, inner)
    raise ValueError("unsupported nesting_mode %r" % mode)


def render_variables(resource_type, resource_schema):
    block = resource_schema["block"]
    cls = classify_attributes(block)
    lines = []
    for name in cls["required"]:
        lines.append("    %s = %s" % (name, hcl_type(block["attributes"][name]["type"])))
    for name in cls["optional"]:
        lines.append(
            "    %s = optional(%s)" % (name, hcl_type(block["attributes"][name]["type"]))
        )
    for name, bt in sorted((block.get("block_types") or {}).items()):
        lines.append("    %s = optional(%s)" % (name, _block_input_type(bt, 4)))
    return (
        _header(resource_type, _provider_of(resource_type))
        + 'variable "items" {\n'
        + '  description = "%s instances, keyed by a stable identifier."\n'
        % resource_type
        + "  type = map(object({\n%s\n  }))\n}\n" % "\n".join(lines)
    )
